"""World loot, pickup, drop, backpack capacity, weapon slots, attachments and death crates.

Every action returns (ok, detail) and never raises on bad input. Item numbers come from
app/game/solo/items.py and are development values, not original Rules of Survival statistics.

GroundLoot has no durability field, so armor and helmet durability for dropped gear is kept in a
module side table keyed by match. Call clear_match(match) when a match is removed.
"""

import math

from solo_engine import items
from solo_engine.geometry import distance, inside_any
from solo_engine.model import (
    DeathCrate,
    GroundLoot,
    Inventory,
    LifeState,
    Participant,
    SoloMatch,
    WeaponSlot,
)

PICKUP_RADIUS = 2.5

# Category weights for one world item. Higher POI loot_weight shifts the tier tables upward.
_CATEGORY_WEIGHTS: tuple[tuple[str, float], ...] = (
    (items.KIND_WEAPON, 25.0),
    (items.KIND_AMMO, 18.0),
    (items.KIND_HEAL, 18.0),
    (items.KIND_ATTACHMENT, 10.0),
    (items.KIND_ARMOR, 8.0),
    (items.KIND_HELMET, 8.0),
    (items.KIND_BACKPACK, 6.0),
    (items.KIND_THROWABLE, 7.0),
)
_WEAPON_WEIGHTS = {"pistol": 30.0, "smg": 25.0, "shotgun": 20.0, "assault_rifle": 18.0, "sniper": 7.0}
_HEAL_WEIGHTS = {"bandage": 50.0, "first_aid_kit": 25.0, "medkit": 8.0, "energy_drink": 17.0}
_HEAL_STACK = {"bandage": 5, "first_aid_kit": 1, "medkit": 1, "energy_drink": 2}
_THROWABLE_WEIGHTS = {"frag": 70.0, "smoke": 30.0}

_MatchKey = tuple[str, int]
_DURABILITY: dict[_MatchKey, dict[str, float]] = {}


def _key(match: SoloMatch) -> _MatchKey:
    return (match.match_id, id(match))


def clear_match(match: SoloMatch) -> None:
    """Forget side-table state for a removed match."""
    _DURABILITY.pop(_key(match), None)


def ground_durability(match: SoloMatch, loot_id: str) -> float | None:
    """Durability stored for a dropped armor or helmet, or None for full durability."""
    return _DURABILITY.get(_key(match), {}).get(loot_id)


# --------------------------------------------------------------------------- capacity


def backpack_capacity(p: Participant) -> float:
    bag = items.BACKPACKS.get(p.inventory.backpack_id or "")
    return items.BASE_BACKPACK_CAPACITY + (bag.capacity_bonus if bag else 0.0)


def backpack_used(p: Participant) -> float:
    return sum(items.item_space(item_id) * qty for item_id, qty in p.inventory.backpack.items() if qty > 0)


def _free(p: Participant) -> float:
    return backpack_capacity(p) - backpack_used(p)


def _fits(p: Participant, item_id: str, quantity: int) -> int:
    """How many of item_id (up to quantity) fit in the backpack now."""
    if quantity <= 0:
        return 0
    unit = items.item_space(item_id)
    if unit <= 0:
        return quantity
    return max(0, min(quantity, int(math.floor(_free(p) / unit + 1e-9))))


def _add_backpack(p: Participant, item_id: str, quantity: int) -> None:
    if quantity > 0:
        p.inventory.backpack[item_id] = p.inventory.backpack.get(item_id, 0) + quantity


def _take_backpack(p: Participant, item_id: str, quantity: int) -> int:
    have = p.inventory.backpack.get(item_id, 0)
    taken = max(0, min(have, quantity))
    if have - taken <= 0:
        p.inventory.backpack.pop(item_id, None)
    else:
        p.inventory.backpack[item_id] = have - taken
    return taken


# --------------------------------------------------------------------------- ground helpers


def _place(
    match: SoloMatch,
    x: float,
    y: float,
    item_id: str,
    quantity: int,
    crate_id: str | None = None,
    durability: float | None = None,
) -> GroundLoot | None:
    if quantity <= 0:
        return None
    loot = GroundLoot(match.new_id("loot"), x, y, item_id, quantity, crate_id)
    match.loot[loot.loot_id] = loot
    if durability is not None:
        _DURABILITY.setdefault(_key(match), {})[loot.loot_id] = durability
    return loot


def _remove_loot(match: SoloMatch, loot_id: str) -> None:
    loot = match.loot.pop(loot_id, None)
    _DURABILITY.get(_key(match), {}).pop(loot_id, None)
    if loot is not None and loot.crate_id is not None:
        if not any(other.crate_id == loot.crate_id for other in match.loot.values()):
            match.crates.pop(loot.crate_id, None)


def _stash_or_drop(match: SoloMatch, p: Participant, item_id: str, quantity: int) -> None:
    """Put quantity into the backpack; whatever does not fit goes to the ground at p."""
    fit = _fits(p, item_id, quantity)
    _add_backpack(p, item_id, fit)
    _place(match, p.x, p.y, item_id, quantity - fit)


def _trim_mag_to_backpack(p: Participant, slot: WeaponSlot) -> None:
    """After a magazine attachment leaves, return rounds above the new capacity to the backpack.

    No match is available here, so the rounds go to the backpack even past capacity.
    """
    cap = items.mag_capacity(slot)
    if slot.mag > cap:
        weapon = items.WEAPONS.get(slot.weapon_id)
        if weapon is not None:
            _add_backpack(p, weapon.ammo_id, slot.mag - cap)
        slot.mag = cap


def _unequip_weapon(match: SoloMatch, p: Participant, index: int) -> WeaponSlot | None:
    """Remove the weapon in slot index. Unloads its mag into the backpack (overflow to ground).

    Attachments are returned on the WeaponSlot for the caller to rehome.
    """
    inv = p.inventory
    if not 0 <= index < len(inv.weapons):
        return None
    slot = inv.weapons[index]
    if slot is None:
        return None
    inv.weapons[index] = None
    weapon = items.WEAPONS.get(slot.weapon_id)
    if weapon is not None and slot.mag > 0:
        _stash_or_drop(match, p, weapon.ammo_id, slot.mag)
    slot.mag = 0
    if inv.active_slot == index:
        p.reload_left = 0.0
        inv.active_slot = None
    return slot


def _rehome_attachments(match: SoloMatch, p: Participant, attachments: dict[str, str]) -> None:
    """Move loose attachments onto a compatible equipped weapon, else backpack, else ground."""
    for attachment_id in attachments.values():
        if not _auto_attach(p, attachment_id):
            _stash_or_drop(match, p, attachment_id, 1)


def _auto_attach(p: Participant, attachment_id: str) -> bool:
    spec = items.ATTACHMENTS.get(attachment_id)
    if spec is None:
        return False
    inv = p.inventory
    order = list(range(len(inv.weapons)))
    if inv.active_slot is not None and inv.active_slot in order:
        order.remove(inv.active_slot)
        order.insert(0, inv.active_slot)
    for index in order:
        slot = inv.weapons[index]
        if slot is None or spec.slot in slot.attachments:
            continue
        if items.is_compatible(slot.weapon_id, attachment_id):
            slot.attachments[spec.slot] = attachment_id
            return True
    return False


# --------------------------------------------------------------------------- world spawn


def _poi_weight(match: SoloMatch, x: float, y: float) -> float:
    best = 0.0
    for poi in match.map.pois:
        if distance(x, y, poi.x, poi.y) <= poi.radius:
            best = max(best, poi.loot_weight)
    return best if best > 0 else 0.5  # outskirts


def _pick(rng, weights: dict[str, float]) -> str:
    keys = list(weights)
    return rng.choices(keys, weights=[weights[k] for k in keys], k=1)[0]


def _tier_weights(weight: float) -> tuple[float, float, float]:
    if weight >= 1.5:
        return (30.0, 45.0, 25.0)
    if weight >= 1.0:
        return (50.0, 35.0, 15.0)
    return (70.0, 25.0, 5.0)


def spawn_world_loot(match: SoloMatch) -> None:
    """Fill match.loot from match.map.loot_spawns. Deterministic for a given match.rng state.

    Spawns inside water or a blocker are skipped. Every weapon spawns with matching ammo nearby.
    """
    rng = match.rng
    categories = [c for c, _ in _CATEGORY_WEIGHTS]
    category_weights = [w for _, w in _CATEGORY_WEIGHTS]
    for x, y in match.map.loot_spawns:
        if inside_any(x, y, match.map.water) or inside_any(x, y, match.map.blockers):
            continue
        weight = _poi_weight(match, x, y)
        count = 1 + (1 if rng.random() < min(0.8, 0.4 * weight) else 0)
        for n in range(count):
            ox, oy = x + 0.6 * n, y
            category = rng.choices(categories, weights=category_weights, k=1)[0]
            tiers = _tier_weights(weight)
            if category == items.KIND_WEAPON:
                weapon_id = _pick(rng, _WEAPON_WEIGHTS)
                _place(match, ox, oy, weapon_id, 1)
                ammo_id = items.WEAPONS[weapon_id].ammo_id
                _place(match, ox, oy + 0.6, ammo_id, items.AMMO[ammo_id] * 2)
            elif category == items.KIND_AMMO:
                ammo_id = rng.choice(sorted(items.AMMO))
                _place(match, ox, oy, ammo_id, items.AMMO[ammo_id])
            elif category == items.KIND_HEAL:
                heal_id = _pick(rng, _HEAL_WEIGHTS)
                _place(match, ox, oy, heal_id, _HEAL_STACK[heal_id])
            elif category == items.KIND_ATTACHMENT:
                _place(match, ox, oy, rng.choice(sorted(items.ATTACHMENTS)), 1)
            elif category == items.KIND_ARMOR:
                level = rng.choices((1, 2, 3), weights=tiers, k=1)[0]
                _place(match, ox, oy, f"armor_{level}", 1)
            elif category == items.KIND_HELMET:
                level = rng.choices((1, 2, 3), weights=tiers, k=1)[0]
                _place(match, ox, oy, f"helmet_{level}", 1)
            elif category == items.KIND_BACKPACK:
                level = rng.choices((1, 2, 3), weights=tiers, k=1)[0]
                _place(match, ox, oy, f"backpack_{level}", 1)
            else:
                _place(match, ox, oy, _pick(rng, _THROWABLE_WEIGHTS), 1)


# --------------------------------------------------------------------------- pickup


def pickup(match: SoloMatch, p: Participant, loot_id: str) -> tuple[bool, str]:
    loot = match.loot.get(loot_id)
    if loot is None:
        return False, "no such loot"
    if not p.alive or p.life != LifeState.GROUNDED:
        return False, "cannot pick up now"
    if distance(p.x, p.y, loot.x, loot.y) > PICKUP_RADIUS:
        return False, "too far"
    if loot.quantity <= 0:
        _remove_loot(match, loot_id)
        return False, "empty"
    kind = items.kind_of(loot.item_id)
    item_id = loot.item_id
    taken = 0
    detail = "ok"
    inv = p.inventory

    if kind == items.KIND_WEAPON:
        index = next((i for i, s in enumerate(inv.weapons) if s is None), None)
        if index is None:
            index = inv.active_slot if inv.active_slot is not None else 0
            old = _unequip_weapon(match, p, index)
            if old is not None:
                _place(match, p.x, p.y, old.weapon_id, 1)
            inv.weapons[index] = WeaponSlot(item_id)
            if old is not None:
                _rehome_attachments(match, p, old.attachments)
            detail = f"swapped:{old.weapon_id if old else ''}"
        else:
            inv.weapons[index] = WeaponSlot(item_id)
        if inv.active_slot is None:
            inv.active_slot = index
        taken = 1
    elif kind in (items.KIND_ARMOR, items.KIND_HELMET):
        is_armor = kind == items.KIND_ARMOR
        spec = (items.ARMORS if is_armor else items.HELMETS)[item_id]
        stored = ground_durability(match, loot_id)
        new_durability = spec.durability if stored is None else stored
        old_id = inv.armor_id if is_armor else inv.helmet_id
        old_durability = inv.armor_durability if is_armor else inv.helmet_durability
        if old_id is not None:
            _place(match, p.x, p.y, old_id, 1, durability=old_durability)
        if is_armor:
            inv.armor_id, inv.armor_durability = item_id, new_durability
        else:
            inv.helmet_id, inv.helmet_durability = item_id, new_durability
        taken = 1
    elif kind == items.KIND_BACKPACK:
        old_id = inv.backpack_id
        new_capacity = items.BASE_BACKPACK_CAPACITY + items.BACKPACKS[item_id].capacity_bonus
        if backpack_used(p) > new_capacity + 1e-9:
            return False, "backpack contents do not fit"
        inv.backpack_id = item_id
        if old_id is not None:
            _place(match, p.x, p.y, old_id, 1)
        taken = 1
    elif kind == items.KIND_ATTACHMENT and _auto_attach(p, item_id):
        taken = 1
        detail = "attached"
    elif kind is not None and items.is_stackable(item_id):
        taken = _fits(p, item_id, loot.quantity)
        if taken <= 0:
            return False, "backpack full"
        _add_backpack(p, item_id, taken)
        if taken < loot.quantity:
            detail = "partial"
    else:
        return False, "unknown item"

    loot.quantity -= taken
    if loot.quantity <= 0:
        _remove_loot(match, loot_id)
    match.emit("pickup", participant_id=p.participant_id, loot_id=loot_id, item_id=item_id, quantity=taken)
    return True, detail


# --------------------------------------------------------------------------- drop


def drop(match: SoloMatch, p: Participant, item_id: str, quantity: int = 1) -> tuple[bool, str]:
    """Drop quantity of item_id at p. Equipped weapons, armor, helmet and bag drop as one item."""
    if not p.alive or p.life in (LifeState.WAITING, LifeState.ON_AIRCRAFT):
        return False, "cannot drop now"
    if not isinstance(quantity, int) or quantity <= 0:
        return False, "bad quantity"
    inv = p.inventory
    if inv.backpack.get(item_id, 0) > 0:
        taken = _take_backpack(p, item_id, quantity)
        if p.healing_item == item_id and inv.backpack.get(item_id, 0) <= 0:
            p.heal_left, p.healing_item = 0.0, None
        _place(match, p.x, p.y, item_id, taken)
        match.emit("drop", participant_id=p.participant_id, item_id=item_id, quantity=taken)
        return True, "ok"
    for index, slot in enumerate(inv.weapons):
        if slot is not None and slot.weapon_id == item_id:
            old = _unequip_weapon(match, p, index)
            if old is None:
                break
            _place(match, p.x, p.y, old.weapon_id, 1)
            _rehome_attachments(match, p, old.attachments)
            if inv.active_slot is None:
                inv.active_slot = next((i for i, s in enumerate(inv.weapons) if s is not None), None)
            match.emit("drop", participant_id=p.participant_id, item_id=item_id, quantity=1)
            return True, "ok"
    if inv.armor_id == item_id:
        _place(match, p.x, p.y, item_id, 1, durability=inv.armor_durability)
        inv.armor_id, inv.armor_durability = None, 0.0
    elif inv.helmet_id == item_id:
        _place(match, p.x, p.y, item_id, 1, durability=inv.helmet_durability)
        inv.helmet_id, inv.helmet_durability = None, 0.0
    elif inv.backpack_id == item_id:
        if backpack_used(p) > items.BASE_BACKPACK_CAPACITY + 1e-9:
            return False, "backpack contents do not fit"
        inv.backpack_id = None
        _place(match, p.x, p.y, item_id, 1)
    else:
        return False, "not carried"
    match.emit("drop", participant_id=p.participant_id, item_id=item_id, quantity=1)
    return True, "ok"


# --------------------------------------------------------------------------- weapons


def equip_weapon(p: Participant, slot: int) -> tuple[bool, str]:
    inv = p.inventory
    if not p.alive:
        return False, "eliminated"
    if not isinstance(slot, int) or not 0 <= slot < len(inv.weapons) or inv.weapons[slot] is None:
        return False, "empty slot"
    if inv.active_slot != slot:
        p.reload_left = 0.0
    inv.active_slot = slot
    return True, "ok"


def attach(p: Participant, slot: int, attachment_id: str) -> tuple[bool, str]:
    """Attach from the backpack onto the weapon in slot. A replaced attachment goes to the backpack."""
    inv = p.inventory
    if not p.alive:
        return False, "eliminated"
    if not isinstance(slot, int) or not 0 <= slot < len(inv.weapons) or inv.weapons[slot] is None:
        return False, "empty slot"
    spec = items.ATTACHMENTS.get(attachment_id)
    if spec is None:
        return False, "not an attachment"
    if inv.backpack.get(attachment_id, 0) <= 0:
        return False, "not carried"
    weapon = inv.weapons[slot]
    if not items.is_compatible(weapon.weapon_id, attachment_id):
        return False, "incompatible"
    _take_backpack(p, attachment_id, 1)
    old = weapon.attachments.get(spec.slot)
    weapon.attachments[spec.slot] = attachment_id
    if old is not None:
        _add_backpack(p, old, 1)  # same space as the one just removed
        _trim_mag_to_backpack(p, weapon)
    return True, "ok"


def detach(p: Participant, slot: int, attachment_slot: str) -> tuple[bool, str]:
    inv = p.inventory
    if not p.alive:
        return False, "eliminated"
    if not isinstance(slot, int) or not 0 <= slot < len(inv.weapons) or inv.weapons[slot] is None:
        return False, "empty slot"
    weapon = inv.weapons[slot]
    attachment_id = weapon.attachments.get(attachment_slot)
    if attachment_id is None:
        return False, "nothing attached"
    if _fits(p, attachment_id, 1) < 1:
        return False, "backpack full"
    del weapon.attachments[attachment_slot]
    _add_backpack(p, attachment_id, 1)
    _trim_mag_to_backpack(p, weapon)
    return True, "ok"


# --------------------------------------------------------------------------- death crate


def create_death_crate(match: SoloMatch, p: Participant) -> str:
    """Move the whole inventory into a crate at p and empty the inventory. Returns the crate id."""
    crate = DeathCrate(match.new_id("crate"), p.participant_id, p.x, p.y)
    match.crates[crate.crate_id] = crate
    inv = p.inventory
    stacks: dict[str, int] = {}

    def add(item_id: str, quantity: int) -> None:
        if quantity > 0:
            stacks[item_id] = stacks.get(item_id, 0) + quantity

    for slot in inv.weapons:
        if slot is None:
            continue
        add(slot.weapon_id, 1)
        weapon = items.WEAPONS.get(slot.weapon_id)
        if weapon is not None:
            add(weapon.ammo_id, slot.mag)
        for attachment_id in slot.attachments.values():
            add(attachment_id, 1)
    for item_id, quantity in inv.backpack.items():
        add(item_id, quantity)
    if inv.backpack_id:
        add(inv.backpack_id, 1)
    for item_id, quantity in stacks.items():
        _place(match, p.x, p.y, item_id, quantity, crate_id=crate.crate_id)
    if inv.armor_id:
        _place(match, p.x, p.y, inv.armor_id, 1, crate.crate_id, durability=inv.armor_durability)
    if inv.helmet_id:
        _place(match, p.x, p.y, inv.helmet_id, 1, crate.crate_id, durability=inv.helmet_durability)
    p.inventory = Inventory()
    p.reload_left = 0.0
    p.heal_left, p.healing_item = 0.0, None
    return crate.crate_id
